-- Hyprland configuration — entry point.
--
-- This file only sequences the modules. Edit the module that owns the setting
-- you care about; the load order below is load-bearing and should not change.
--
--   env.lua        environment variables and session startup hooks
--   settings.lua   input, general, decoration, misc
--   gestures.lua   touchpad gestures
--   animations.lua animation curves
--   rules.lua      window and layer rules
--   monitors.lua   generated: workspace ranges and per-output orientation
--   dms/*          generated by DankMaterialShell — do not hand-edit
--   quattro.lua    scrolling-layout helpers, gap state, hyprgrass bindings
--   binds.lua      global bind helpers, then the user keybinds

require("env")
require("settings")
require("gestures")
require("animations")
require("rules")

-- DankMaterialShell writes these. They must load before quattro.lua, which
-- layers workspace behaviour on top of the generated layout.
require("dms.colors")
require("dms.border-colors")
require("dms.outputs")
require("dms.layout")
require("dms.cursor")

-- Generated by the installer from the connected displays; quattro.lua reads
-- the globals it defines.
require("monitors")
require("quattro")
require("binds")

require("dms-theme-sync")
